<!-- jhjm-fox-say Puzzle | Generated by EterIll's CCXC Problem Template X -->
<template>

    <div class="container">
        <div v-if="globalError" class="alert alert-danger">
            {{ globalError }}
        </div>

        <!-- Block 1: 选框 -->
        <table class="questions-table">
            <tbody>
                <tr>
                    <td v-for="i in 8" :key="'q' + (i-1)" :id="'q' + (i-1)"
                        :class="{ 'solved-question': isSolved(i-1), 'selected-question': currentActiveQuestion === i-1 }"
                        @click="switchQuestion(i-1)">
                        {{ questionIds[i-1] }}
                    </td>
                </tr>
                <tr>
                    <td v-for="i in 8" :key="'q' + (i+7)" :id="'q' + (i+7)"
                        :class="{ 'solved-question': isSolved(i+7), 'selected-question': currentActiveQuestion === i+7 }"
                        @click="switchQuestion(i+7)">
                        {{ questionIds[i+7] }}
                    </td>
                </tr>
            </tbody>
        </table>

        <hr />

        <!-- Block 2: 提示 -->
        <div class="container p-5 border border-black mb-3">
            <div id="hint1" class="text-end my-3">{{ hint1Text }}</div>
            <div class="my-3 border border-black"></div>
            <div id="hint2" class="text-start my-3">{{ hint2Text }}</div>

            <!-- Block 3: 提交 -->
            <form @submit.prevent="submit" autocomplete="off">
                <div class="my-3 row">
                    <input id="guess" v-model="guessWord" type="text" :disabled="isSubmitting || isCurrentSolved">
                    <button id="submit" class="btn galatic-btn" type="submit" :disabled="isSubmitting || isCurrentSolved">确认</button>
                </div>
            </form>

            <div v-show="showResult" class="guess-result m-auto text-center col-4 col-md-2">
                <div id="guess-reflection" class="alert" :class="resultAlertClass" role="alert">{{ resultText }}</div>
            </div>
        </div>

        <!-- Block 4: 冠军感言 -->
        <div v-show="showReflection" id="reflection-container" class="container mb-3">
            <h3>冠军感言</h3>
            <div id="reflection" class="container-fluid text-center">{{ reflectionText }}</div>
        </div>

        <div>
            <h4>去掉答案的第一个字后，凯撒主任将会从主持人开始颁发奖金……</h4>
            <ul>
                <li>¥190</li>
                <li>¥200</li>
                <li>¥150</li>
                <li>¥150</li>
                <li>¥150</li>
                <li>¥50</li>
                <li>¥0</li>
                <li>¥190</li>
                <li>¥150</li>
                <li>¥120</li>
                <li>¥20</li>
                <li>¥140</li>
                <li>¥250</li>
                <li>¥0</li>
                <li>¥190</li>
                <li>¥200</li>
            </ul>
        </div>
    </div>

</template>
<style>

.questions-table {
    border: 1px solid #000;
    border-collapse: collapse;
    margin: auto;
    padding: 5px;
}
.questions-table td {
    border: 1px solid #000;
    padding: 5px;
    width: 5rem;
    text-align: center;
    cursor: pointer;
}
#reflection-container {
    border-radius: 20px;
    padding: 20px;
    border: 2px solid black;
    background-color: #EAF7FA;
}
#reflection-container h2 {
    margin-top: 0;
    margin-bottom: 2rem;
}
#guess {
    width: 60%;
    margin-left: 10%;
    margin-right: 10%;
}
#submit {
    width: 20%;
}
.solved-question {
    background-color: #4de886;
}
.selected-question {
    background-color: #000!important;
    color: #fff;
}
.galatic-btn {
    background: rgb(0, 85, 170);
    color: #fff;
}
.galatic-btn:hover,
.galatic-btn:focus {
    color: #fff;
    background: #2af;
}

</style>


